/* ResearchDeck: source-backed presentation pages.
 * API: render(module, index) -> HTML; mount() -> attach interactions.
 * Read-only data: RESEARCH_CONTENT.pages[module.research], SITE_DATA.images.
 * No plots, measurements or results are generated by this renderer.
 */
(function () {
  'use strict';

  const states = new Map();
  let mounted = false;
  let sourceDialog = null;
  let dialogTrigger = null;

  const escapeHTML = value => String(value == null ? '' : value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
  const list = value => Array.isArray(value) ? value : [];
  const identifier = value => String(value || 'research').replace(/[^a-zA-Z0-9_-]/g, '-');
  const contentFor = key => window.RESEARCH_CONTENT && window.RESEARCH_CONTENT.pages && window.RESEARCH_CONTENT.pages[key];
  const imageFor = key => window.SITE_DATA && window.SITE_DATA.images && window.SITE_DATA.images[key];
  const safeImageURL = value => /^(?:\.\.?\/|\/|https?:\/\/|data:image\/|blob:)/i.test(String(value || '')) ? String(value) : '';

  function metricsHTML(metrics, compact) {
    const entries = list(metrics);
    if (!entries.length) return '';
    return `<dl class="rd-metrics${compact ? ' rd-metrics-compact' : ''}">${entries.map(metric =>
      `<div><dd>${escapeHTML(metric.value)}</dd><dt>${escapeHTML(metric.label)}</dt></div>`
    ).join('')}</dl>`;
  }

  function tableHTML(table) {
    if (!table || !list(table.rows).length) return '';
    const headers = list(table.headers);
    return `<div class="rd-table-wrap" data-rd-scroll><table class="rd-table">${table.caption ? `<caption>${escapeHTML(table.caption)}</caption>` : ''}${headers.length ? `<thead><tr>${headers.map(header => `<th scope="col">${escapeHTML(header)}</th>`).join('')}</tr></thead>` : ''}<tbody>${table.rows.map((row, index) => `<tr${index === table.highlightRow ? ' class="rd-highlight-row"' : ''}>${list(row).map((cell, column) => column === 0 ? `<th scope="row">${escapeHTML(cell)}</th>` : `<td>${escapeHTML(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }

  function itemsHTML(items) {
    const entries = list(items);
    if (!entries.length) return '';
    return `<ul class="rd-items">${entries.map(item => `<li>${item.title ? `<strong>${escapeHTML(item.title)}</strong>` : ''}${item.text ? `<span>${escapeHTML(item.text)}</span>` : ''}</li>`).join('')}</ul>`;
  }

  function imageHTML(view, id) {
    const image = imageFor(view.imageKey);
    if (!image || !safeImageURL(image.src)) return '';
    const title = image.title || view.headline || 'Research figure';
    const caption = view.imageCaption == null ? title : view.imageCaption;
    return `<figure class="rd-figure"><button type="button" class="rd-image-button" data-rd-image="${escapeHTML(view.imageKey)}" aria-label="Enlarge figure: ${escapeHTML(title)}"><img src="${escapeHTML(safeImageURL(image.src))}" alt="${escapeHTML(title)}" loading="lazy" decoding="async"${caption ? ` aria-describedby="${id}-image-caption"` : ''}><span class="rd-expand-label" aria-hidden="true">Enlarge ↗</span></button>${caption ? `<figcaption id="${id}-image-caption">${escapeHTML(caption)}</figcaption>` : ''}</figure>`;
  }

  function stepDetailHTML(state) {
    const step = state.steps[state.step] || {};
    return `${step.title ? `<h3>${escapeHTML(step.title)}</h3>` : ''}${step.text ? `<p>${escapeHTML(step.text)}</p>` : ''}${step.code ? `<pre class="rd-code" tabindex="0" aria-label="Processing notation"><code>${escapeHTML(step.code)}</code></pre>` : ''}`;
  }

  function stepsHTML(state, view) {
    return `<div class="rd-process"><div class="rd-process-heading"><span>PROCESS WALKTHROUGH</span><span data-rd-step-count>${state.step + 1} / ${state.steps.length}</span></div><div class="rd-step-list" role="tablist" aria-label="Processing steps" aria-orientation="vertical">${state.steps.map((step, index) => `<button type="button" class="rd-step-tab" role="tab" id="${state.id}-step-${index}" aria-controls="${state.id}-step-detail" aria-selected="${index === state.step}" tabindex="${index === state.step ? 0 : -1}" data-rd-step="${index}"><span class="rd-step-number" aria-hidden="true">${String(index + 1).padStart(2, '0')}</span><span>${escapeHTML(String(step.label || step.title || `Step ${index + 1}`).replace(/^\d+\s+/, ''))}</span></button>`).join('')}</div><div class="rd-step-detail" id="${state.id}-step-detail" role="tabpanel" aria-labelledby="${state.id}-step-${state.step}" tabindex="0" data-rd-scroll>${stepDetailHTML(state)}</div>${view.note ? `<p class="rd-note">${escapeHTML(view.note)}</p>` : ''}</div>`;
  }

  function copyHTML(view, tableConsumed) {
    return `<div class="rd-copy" data-rd-scroll>${view.headline ? `<h3>${escapeHTML(view.headline)}</h3>` : ''}${view.body ? `<p class="rd-body">${escapeHTML(view.body)}</p>` : ''}${metricsHTML(view.metrics, false)}${!tableConsumed ? tableHTML(view.table) : ''}${itemsHTML(view.items)}${view.note ? `<p class="rd-note">${escapeHTML(view.note)}</p>` : ''}</div>`;
  }

  function panelHTML(state) {
    const view = state.views[state.view] || {};
    const figure = imageHTML(view, state.id);
    const tableIsPrimary = !figure && view.table && list(view.table.rows).length > 0;
    const visual = figure || (tableIsPrimary ? `<div class="rd-primary-table" data-rd-scroll>${tableHTML(view.table)}</div>` : '');
    const hasSteps = state.steps.length > 0;
    const summary = hasSteps && (view.headline || view.body) ? `<div class="rd-visual-summary">${view.headline ? `<h3>${escapeHTML(view.headline)}</h3>` : ''}${view.body ? `<p>${escapeHTML(view.body)}</p>` : ''}</div>` : '';
    return `<div class="rd-workspace${visual ? '' : ' rd-copy-only'}${hasSteps ? ' rd-with-steps' : ''}">${visual ? `<div class="rd-visual">${summary}${visual}</div>` : ''}${hasSteps ? stepsHTML(state, view) : copyHTML(view, tableIsPrimary)}</div>`;
  }

  function viewTabsHTML(state) {
    if (state.views.length < 2) return `<span class="rd-view-label">${escapeHTML(state.views[0] && state.views[0].label || 'ANALYSIS VIEW')}</span>`;
    return `<div class="rd-view-tabs" role="tablist" aria-label="Analysis views">${state.views.map((view, index) => `<button type="button" role="tab" class="rd-view-tab" id="${state.id}-view-${index}" aria-controls="${state.id}-panel" aria-selected="${index === state.view}" tabindex="${index === state.view ? 0 : -1}" data-rd-view="${index}">${escapeHTML(view.label || view.id || `View ${index + 1}`)}</button>`).join('')}</div>`;
  }

  function summaryFiguresHTML(state) {
    return `<div class="rd-summary-gallery">${list(state.page.figures).map((figure, figureIndex) => {
      const id = `${state.id}-figure-${figureIndex}`;
      const visual = imageHTML(figure, id);
      if (!visual) return '';
      const title = figure.title || imageFor(figure.imageKey).title || `Figure ${figureIndex + 1}`;
      return `<article class="rd-summary-card" aria-labelledby="${id}-title"><header class="rd-summary-card-header"><h3 id="${id}-title">${escapeHTML(title)}</h3>${figure.subtitle ? `<p>${escapeHTML(figure.subtitle)}</p>` : ''}</header>${visual}${figure.metric ? `<div class="rd-summary-card-metric">${metricsHTML([figure.metric], false)}</div>` : ''}</article>`;
    }).join('')}</div>`;
  }

  function summaryHTML(state, index) {
    const { id, module, page } = state;
    const view = state.views[0] || {};
    const paired = list(page.figures).length > 0;
    const visual = paired ? summaryFiguresHTML(state) : `${imageHTML(view, id)}${list(page.metrics).length ? `<div class="rd-summary-metrics">${metricsHTML(page.metrics, false)}</div>` : ''}`;
    const paragraphs = list(page.summary).map((item, itemIndex) =>
      `<section class="rd-summary-item${itemIndex === 1 ? ' rd-summary-result' : ''}" aria-labelledby="${id}-summary-${itemIndex}"><h3 id="${id}-summary-${itemIndex}">${escapeHTML(item.label)}</h3>${item.text ? `<p>${escapeHTML(item.text)}</p>` : ''}${item.text2 ? `<p>${escapeHTML(item.text2)}</p>` : ''}</section>`
    ).join('');
    const takeaway = String(page.takeaway || '').trim();
    return `<section class="chapter research-chapter rd-summary${paired ? ' rd-summary-paired' : ''}" id="${id}" data-research-key="${escapeHTML(module.research)}"><div class="slide-inner rd-slide-inner"><div class="chapter-number">${String(index + 1).padStart(2, '0')}</div><div class="eyebrow">${escapeHTML(module.eyebrow)}</div><h2 id="${id}-heading">${escapeHTML(module.title)}</h2><div class="rd-summary-main"><div class="rd-summary-visual">${visual}</div><div class="rd-summary-copy" data-rd-scroll>${paragraphs}</div></div><footer class="rd-summary-footer${takeaway ? '' : ' rd-summary-footer-quiet'}">${takeaway ? `<p class="rd-takeaway">${escapeHTML(takeaway)}</p>` : ''}<button type="button" class="rd-source-button" data-rd-source>Sources &amp; scope <span aria-hidden="true">↗</span></button></footer></div></section>`;
  }

  function render(module, index) {
    const page = contentFor(module.research);
    if (!page) return '';
    const id = identifier(module.id);
    const old = states.get(id);
    if (old && old.timer) window.clearInterval(old.timer);
    const state = { id, key: module.research, module, page, views: list(page.views), steps: list(page.steps), view: 0, step: 0, playing: false, timer: null, section: null };
    if (!state.views.length) state.views.push({ label: 'OVERVIEW', headline: module.title, body: '' });
    states.set(id, state);
    if (page.layout === 'summary') return summaryHTML(state, index);
    const panelLabel = state.views.length > 1 ? `${id}-view-0` : `${id}-heading`;
    return `<section class="chapter research-chapter" id="${id}" data-research-key="${escapeHTML(module.research)}"><div class="slide-inner rd-slide-inner"><div class="chapter-number">${String(index + 1).padStart(2, '0')}</div><div class="eyebrow">${escapeHTML(module.eyebrow)}</div><h2 id="${id}-heading">${escapeHTML(module.title)}</h2>${module.intro ? `<p class="lead">${escapeHTML(module.intro)}</p>` : ''}${metricsHTML(page.metrics, true)}<div class="rd-stage"><div class="rd-toolbar">${viewTabsHTML(state)}${state.steps.length > 1 ? `<button type="button" class="rd-play-button" data-rd-play aria-pressed="false" aria-label="Play processing walkthrough"><span aria-hidden="true">▶</span> Play steps</button>` : ''}</div><div class="rd-panel" id="${id}-panel" role="tabpanel" aria-labelledby="${panelLabel}">${panelHTML(state)}</div></div><footer class="rd-footer"><p class="rd-takeaway">${escapeHTML(page.takeaway || module.question || '')}</p><button type="button" class="rd-source-button" data-rd-source>Sources &amp; scope <span aria-hidden="true">↗</span></button></footer></div></section>`;
  }

  function updateStep(state, index, moveFocus) {
    if (!state.steps.length || !state.section) return;
    state.step = (index + state.steps.length) % state.steps.length;
    const buttons = state.section.querySelectorAll('[data-rd-step]');
    buttons.forEach((button, buttonIndex) => {
      button.setAttribute('aria-selected', String(buttonIndex === state.step));
      button.tabIndex = buttonIndex === state.step ? 0 : -1;
    });
    const detail = state.section.querySelector('.rd-step-detail');
    if (detail) {
      detail.innerHTML = stepDetailHTML(state);
      detail.setAttribute('aria-labelledby', `${state.id}-step-${state.step}`);
      detail.scrollTop = 0;
    }
    const count = state.section.querySelector('[data-rd-step-count]');
    if (count) count.textContent = `${state.step + 1} / ${state.steps.length}`;
    if (moveFocus && buttons[state.step]) buttons[state.step].focus({ preventScroll: true });
  }

  function updateView(state, index, moveFocus) {
    state.view = (index + state.views.length) % state.views.length;
    const buttons = state.section.querySelectorAll('[data-rd-view]');
    buttons.forEach((button, buttonIndex) => {
      button.setAttribute('aria-selected', String(buttonIndex === state.view));
      button.tabIndex = buttonIndex === state.view ? 0 : -1;
    });
    const panel = state.section.querySelector('.rd-panel');
    panel.innerHTML = panelHTML(state);
    panel.setAttribute('aria-labelledby', state.views.length > 1 ? `${state.id}-view-${state.view}` : `${state.id}-heading`);
    if (moveFocus && buttons[state.view]) buttons[state.view].focus({ preventScroll: true });
  }

  function activeOnScreen(state) {
    if (!state.section || document.hidden) return false;
    if (document.body.classList.contains('focus')) return state.section.classList.contains('in-focus');
    const rect = state.section.getBoundingClientRect();
    return rect.top < window.innerHeight * 0.8 && rect.bottom > window.innerHeight * 0.2;
  }

  function setPlaying(state, playing) {
    if (state.timer) window.clearInterval(state.timer);
    state.timer = null;
    state.playing = Boolean(playing && state.steps.length > 1);
    const button = state.section && state.section.querySelector('[data-rd-play]');
    if (button) {
      button.setAttribute('aria-pressed', String(state.playing));
      button.setAttribute('aria-label', state.playing ? 'Pause processing walkthrough' : 'Play processing walkthrough');
      button.innerHTML = state.playing ? '<span aria-hidden="true">Ⅱ</span> Pause steps' : '<span aria-hidden="true">▶</span> Play steps';
    }
    if (state.playing) {
      state.timer = window.setInterval(() => {
        if (!activeOnScreen(state) || (sourceDialog && sourceDialog.open)) { setPlaying(state, false); return; }
        if (state.step === state.steps.length - 1) { setPlaying(state, false); return; }
        updateStep(state, state.step + 1, false);
      }, 5500);
    }
  }

  function createSourceDialog() {
    if (sourceDialog) return sourceDialog;
    sourceDialog = document.createElement('dialog');
    sourceDialog.className = 'rd-source-dialog';
    sourceDialog.id = 'research-source-dialog';
    sourceDialog.setAttribute('aria-labelledby', 'research-source-title');
    sourceDialog.setAttribute('aria-modal', 'true');
    sourceDialog.innerHTML = '<div class="rd-dialog-shell"><header class="rd-dialog-header"><div><p>READ THE EVIDENCE</p><h2 id="research-source-title">Sources and scope</h2></div><button type="button" class="rd-dialog-close" aria-label="Close sources and scope">Close ×</button></header><div class="rd-dialog-content" tabindex="0" aria-label="Source details" data-rd-scroll></div></div>';
    document.body.appendChild(sourceDialog);
    sourceDialog.querySelector('.rd-dialog-close').addEventListener('click', closeSources);
    sourceDialog.addEventListener('cancel', event => { event.preventDefault(); closeSources(); });
    sourceDialog.addEventListener('click', event => {
      if (event.target !== sourceDialog) return;
      const box = sourceDialog.getBoundingClientRect();
      if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) closeSources();
    });
    sourceDialog.addEventListener('wheel', event => event.stopPropagation(), { passive: true });
    return sourceDialog;
  }

  function openSources(state, trigger) {
    const dialog = createSourceDialog();
    const source = state.page.source || {};
    dialogTrigger = trigger;
    setPlaying(state, false);
    dialog.querySelector('#research-source-title').textContent = source.title || state.module.title || 'Sources and scope';
    dialog.querySelector('.rd-dialog-content').innerHTML = `<section class="rd-source-list"><h3>Source material</h3>${list(source.items).length ? list(source.items).map(item => `<div class="rd-source-entry"><h4>${escapeHTML(item.label)}</h4><p>${escapeHTML(item.text)}</p></div>`).join('') : '<p>Source details were not supplied for this page.</p>'}</section>${list(source.limitations).length ? `<section class="rd-scope-list"><h3>Scope of this demonstration</h3><ul>${source.limitations.map(item => `<li>${escapeHTML(item)}</li>`).join('')}</ul></section>` : ''}`;
    if (typeof dialog.showModal === 'function') dialog.showModal();
    else dialog.setAttribute('open', '');
    dialog.querySelector('.rd-dialog-content').scrollTop = 0;
    dialog.querySelector('.rd-dialog-close').focus({ preventScroll: true });
  }

  function closeSources() {
    if (!sourceDialog || !sourceDialog.open) return;
    if (typeof sourceDialog.close === 'function') sourceDialog.close();
    else sourceDialog.removeAttribute('open');
    if (dialogTrigger && dialogTrigger.isConnected) dialogTrigger.focus({ preventScroll: true });
    dialogTrigger = null;
  }

  function handleDialogKey(event) {
    if (!sourceDialog || !sourceDialog.open) return;
    if (event.key === 'Escape') { event.preventDefault(); event.stopImmediatePropagation(); closeSources(); return; }
    if (event.key === 'Tab') {
      const focusable = Array.from(sourceDialog.querySelectorAll('button, a[href], input, textarea, select, [tabindex]:not([tabindex="-1"])')).filter(element => !element.disabled && element.getClientRects().length);
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
    // Do not let the underlying presentation advance while reading sources.
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'p', 'P', 'Home', 'End', ' '].includes(event.key)) event.stopImmediatePropagation();
  }

  function attachSection(state) {
    const section = document.getElementById(state.id);
    if (!section || section.dataset.rdMounted === 'true') return;
    state.section = section;
    section.dataset.rdMounted = 'true';
    section.addEventListener('click', event => {
      const target = event.target.closest('button');
      if (!target || !section.contains(target)) return;
      if (target.hasAttribute('data-rd-view')) { updateView(state, Number(target.dataset.rdView), false); return; }
      if (target.hasAttribute('data-rd-step')) { setPlaying(state, false); updateStep(state, Number(target.dataset.rdStep), false); return; }
      if (target.hasAttribute('data-rd-play')) {
        if (!state.playing && state.step === state.steps.length - 1) updateStep(state, 0, false);
        setPlaying(state, !state.playing); return;
      }
      if (target.hasAttribute('data-rd-source')) { openSources(state, target); return; }
      if (target.hasAttribute('data-rd-image') && typeof window.showImg === 'function') window.showImg(target.dataset.rdImage);
    });
    section.addEventListener('keydown', event => {
      const target = event.target.closest('button');
      if (!target) return;
      const isView = target.hasAttribute('data-rd-view'), isStep = target.hasAttribute('data-rd-step');
      const keys = isStep ? ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Home', 'End'] : ['ArrowLeft', 'ArrowRight', 'Home', 'End'];
      if ((!isView && !isStep) || !keys.includes(event.key)) return;
      event.preventDefault(); event.stopPropagation();
      const current = isView ? state.view : state.step;
      const count = isView ? state.views.length : state.steps.length;
      const next = event.key === 'Home' ? 0 : event.key === 'End' ? count - 1 : current + (['ArrowLeft', 'ArrowUp'].includes(event.key) ? -1 : 1);
      if (isStep) { setPlaying(state, false); updateStep(state, next, true); }
      else updateView(state, next, true);
    });
    section.addEventListener('wheel', event => {
      if (event.target.closest('[data-rd-scroll]') || window.matchMedia('(max-width: 820px)').matches) event.stopPropagation();
    }, { passive: true });
  }

  function mount() {
    states.forEach(attachSection);
    if (mounted) return;
    mounted = true;
    document.addEventListener('keydown', handleDialogKey, true);
    document.addEventListener('visibilitychange', () => { if (document.hidden) states.forEach(state => setPlaying(state, false)); });
    window.addEventListener('pagehide', () => states.forEach(state => setPlaying(state, false)));
  }

  window.ResearchDeck = Object.freeze({ render, mount });
})();
